import path from "node:path";
import type { GeneratorContext } from "@rexeus/typeweaver-gen";
import { buildCommandOperationModels } from "./model.js";
import type { CommandOperationModel } from "./model.js";

const generatedHeader = `/**
 * This file was automatically generated by TypeWeaver.
 * DO NOT EDIT. Modify the source contract and generate again.
 *
 * @generated by @rexeus/typeweaver-command
 */
`;

const requestInputLines = (model: CommandOperationModel): readonly string[] => {
  const lines: string[] = [];
  if (model.hasHeader) lines.push("header: validatedRequest.header,");
  if (model.hasParam) lines.push("param: validatedRequest.param,");
  if (model.hasQuery) lines.push("query: validatedRequest.query,");
  if (model.hasBody) lines.push("body: validatedRequest.body,");
  return lines;
};

const rawRequestLines = (model: CommandOperationModel): readonly string[] => {
  const lines: string[] = [];
  if (model.hasHeader) {
    lines.push(
      `header: { ...${JSON.stringify(model.headerDefaults)}, ...context.defaultHeaders, ...context.request.header },`
    );
  }
  if (model.hasParam) lines.push("param: context.request.param,");
  if (model.hasQuery) {
    lines.push("query: { ...context.defaultQuery, ...context.request.query },");
  }
  if (model.hasBody) lines.push("body: context.request.body,");
  return lines;
};

const operationSource = (model: CommandOperationModel): string => {
  const resourceClass = `${model.resourceName[0]?.toUpperCase() ?? ""}${model.resourceName.slice(1)}Client`;
  const operationClass = model.exportName.replace(/Command$/u, "");
  const requestInput = requestInputLines(model);
  const rawInput = rawRequestLines(model);
  const commandConstruction =
    requestInput.length === 0
      ? `new ${operationClass}RequestCommand()`
      : `new ${operationClass}RequestCommand({
${requestInput.map(line => `      ${line}`).join("\n")}
    })`;

  return `${generatedHeader}
import { HttpMethod } from "@rexeus/typeweaver-core";
import { defineGeneratedCommand } from "../../lib/command/index.js";
import { ${resourceClass} } from "../../${model.resourceName}/${resourceClass}.js";
import { ${operationClass}RequestCommand } from "../../${model.resourceName}/${operationClass}RequestCommand.js";
import { ${operationClass}RequestValidator } from "../../${model.resourceName}/${operationClass}RequestValidator.js";

const requestValidator = new ${operationClass}RequestValidator();

export const ${model.exportName} = defineGeneratedCommand({
  name: ${JSON.stringify(model.commandName)},
  operationId: ${JSON.stringify(model.operationId)},
  summary: ${JSON.stringify(model.summary)},
  inputs: ${JSON.stringify(model.inputs, null, 2)},
  headerDefaults: ${JSON.stringify(model.headerDefaults, null, 2)},
  security: ${JSON.stringify(model.security, null, 2)},
  hasBody: ${JSON.stringify(model.hasBody)},
  ${model.bodyTransport === undefined ? "" : `bodyTransport: ${JSON.stringify(model.bodyTransport)},`}
  execute: async context => {
    const validatedRequest = requestValidator.validate({
      method: HttpMethod.${model.method},
      path: ${JSON.stringify(model.path)},
${rawInput.map(line => `      ${line}`).join("\n")}
    });
    const client = new ${resourceClass}({
      baseUrl: context.baseUrl,
      defaultHeaders: context.defaultHeaders,
      defaultQuery: context.defaultQuery,
      signal: context.signal,
    });
    return client.send(${commandConstruction});
  },
});
`;
};

const cliSource = (models: readonly CommandOperationModel[]): string => {
  const imports = models
    .map(
      model =>
        `import { ${model.exportName} } from "./operations/${model.exportName}.js";`
    )
    .join("\n");
  const commands = models.map(model => model.exportName).join(",\n    ");
  return `${generatedHeader}
import { runGeneratedCommandCli } from "../lib/command/index.js";
${imports}

process.exitCode = await runGeneratedCommandCli({
  programName: "typeweaver-api",
  commands: [
    ${commands}
  ],
});
`;
};

export const generateCommandClient = (context: GeneratorContext): void => {
  const models = buildCommandOperationModels(context.normalizedSpec);
  for (const model of models) {
    context.writeFile(
      path.join("command", "operations", `${model.exportName}.ts`),
      operationSource(model)
    );
  }
  context.writeFile(path.join("command", "cli.mts"), cliSource(models));
};
